:root {
	/* Colors */
	--color-primary: #192f7a;
	--color-dark-gray: rgb(37, 37, 37);
	--color-medium-gray: rgb(66, 66, 66);
	--color-lightest-gray: rgb(215, 215, 215);

	/* Font sizes */
	--fs-pt-6: 6pt;
	--fs-pt-7: 7pt;
	--fs-pt-8: 8pt;
	--fs-pt-9: 9pt;
	--fs-pt-10: 10pt;
	--fs-pt-15: 15pt;
	--fs-pt-30: 30pt;
  }


@media print {
	* {
		-webkit-print-color-adjust: exact;
		print-color-adjust: exact;
	}
}

* {
	font-family: Calibri, Candara, Segoe, "Segoe UI", Optima, Arial, sans-serif;
}

.master-container{
    max-width: 20cm;
    max-height: 20cm;
    padding: 1cm;
}

.print-format td {
	padding: 0 !important;
}

body {
	border-width: 1pt;
	padding-left: 15pt;
	padding-right: 15pt;
}

.logo-container {
	margin-top: 20pt;
}

.company-details {
	font-weight: 400;
	color: var(--color-dark-gray);
	font-size: 7pt;
}

.header {
	width: 100%;
	display: flex;
	flex-direction: row;
	justify-content: flex-end;
	align-items: flex-start;
	margin-top: 0pt !important;
}

.section-break {
	margin-top: 10pt !important;
	margin-bottom: 10pt !important;
}

.title {
	font-weight: 600;
	color: var(--color-primary);
	font-size: 30pt;
	align-self: center;
	margin-top: 0pt !important;
	text-align: right;
}


.title.so-label {
	margin: 0;
	padding: 0;
}

.title.so-series {
	margin: 0;
	padding: 0;
	font-weight: 100;
	font-size: 15pt;
	margin-top: -5pt !important;
	color: var(--color-dark-gray);
	letter-spacing: 0;
}

.label-unique {
	color: var(--color-dark-gray);
}

.contact-information {
	display: flex;
	justify-content: space-between;
}

.info-block {
	display: flex;
	vertical-align: top;
}

.info-block tr {
	color: rgb(58, 58, 58);
	font-size: 10pt;
	font-weight: 800;
}

td.label-unique {
	padding-right: 10pt !important;
}

.info-block.company td {
	color: var(--color-dark-gray);
	overflow: hidden;
}


/* ─── Order Details ─────────────────────────────────────────────────────────── */

.order-details {
	margin-top: 15pt;
	width: 100%;
	border-collapse: collapse;
	table-layout: auto;    /* allow columns to size to content */
	font-size: 8pt;
}

/* base cell styles */
.order-details th,
.order-details td {
	padding: 0.5em !important;
	border: 1px solid var(--color-dark-gray);
	word-wrap: break-word;
	white-space: normal;
}

/* fixed hint widths for columns 1 & 2 */
.order-details th:nth-child(1),
.order-details td:nth-child(1) {
	width: 75%;
}

.order-details th:nth-child(2),
.order-details td:nth-child(2) {
	width: 25%;
}

/* prevent wrapping in qty, unit, rate, amount and let them expand */
.order-details th:nth-child(n+3),
.order-details td:nth-child(n+3) {
	white-space: nowrap;
	word-wrap: normal;
}

.order-details th {
	background-color: var(--color-primary);
	color: white;
	font-size: 10pt;
	font-weight: 600;
	padding: 3pt 8pt;
	border-left-color:  var(--color-primary);
	border-right-color: var(--color-primary);
	border-bottom:      2px solid #005580;
}

/* ─── Remarks & Totals ─────────────────────────────────────────────────────── */

.info-block.remarks-details {
	display: flex;
	font-size: 9pt;
	font-weight: 600;
	color: var(--color-dark-gray);
	gap: 5pt;
	width: 50%;
}

.remarks {
	font-weight: 400;
	color: var(--color-dark-gray);
}

.transaction-details-container {
	display: flex;
	justify-content: space-between;
	align-items: flex-start;
	margin-top: 10pt;
}

.unbold {
    font-weight: 200;
}

.remarks-details > tbody > tr > td:first-child {
	align-self: flex-start;
}

.info-block.remarks-details td {
	vertical-align: top;
}

/* ─── Footer ───────────────────────────────────────────────────────────────── */

.footer {
	position: fixed;
	left: 0;
	bottom: 0;
	width: 100%;
	color: white;
	text-align: center;
}

.signature-container {
	display: flex;
	margin-top: 40pt;
	gap: 20pt;
}
